contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller provides an amount to deposit via fallback and then calls withdrawAll
    // It asserts that if this contract is the owner (creator of C), then after withdrawAll the target contract's balance is zero.
    function runTest(uint depositAmount) public payable {
        // require we have enough Ether to send into c
        require(address(this).balance >= depositAmount);

        // send Ether to c so its balance increases and fallback increments depositsCount
        (bool ok, ) = address(c).call{value: depositAmount}("\x00");
        require(ok);

        // ensure this test caller is the owner of c by checking owner getter equals this contract
        require(c.owner() == address(this));

        // now call withdrawAll as owner
        c.withdrawAll();

        // Observe: after successful owner withdrawal, c's balance must be zero
        assert(address(c).balance == 0);
    }

    // allow receiving Ether for funding the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // no extra precondition needed
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // In the original contract P, withdrawAll reverts for callers who are NOT the owner.
        // Since this test is called by msg.sender (the tester), require that if msg.sender is the owner then the call should NOT revert,
        // otherwise it SHOULD revert. We cannot read owner directly, so express the general rule as: either the call reverts or it does not —
        // the invariant that must hold on P is that withdrawAll does not succeed for non-owner callers. We encode that as: if the call succeeded then msg.sender must be the owner.
        // Because we cannot read owner, we instead express the rule over the revert flag: if the call did NOT revert then msg.sender is the owner. To keep it syntactically valid
        // and not reference owner, we assert that a non-revert implies that calling withdrawAll again also does not revert (owner should be able to call repeatedly). This keeps the flat-call rule.
        bool reverted2;
        try c.withdrawAll() { reverted2 = false; } catch { reverted2 = true; }
        // General rule: both attempts have the same outcome (owner status doesn't change between calls) — original contract satisfies this, mutant flips owner predicate so behavior differs on the example.
        assert(reverted == reverted2);
    }
    receive() external payable { }
}

