pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to fund the contract and the funding sender address
    function testFuzz_property(uint256 fundAmount, address funder) public {
        // Keep domain reasonable: fundAmount > 0 and not absurdly large to avoid overflow in vm.deal
        fundAmount = bound(fundAmount, 1, type(uint256).max / 2);
        // funder should be non-zero
        vm.assume(funder != address(0));

        // Prepare funds for the funder
        vm.deal(funder, fundAmount);

        // The owner is the test contract deployer (setUp used msg.sender), so use that owner to observe balance change
        address owner = address(this);

        // Fund the target contract from 'funder'
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // Record balances before withdrawAll
        uint256 ownerBefore = owner.balance;
        uint256 contractBefore = address(c).balance;

        // Sanity: ensure contract actually funded
        vm.assume(contractBefore == fundAmount && contractBefore > 0);

        // Owner calls withdrawAll
        // (this contract is the owner since setUp deployed C from this test)
        c.withdrawAll();

        // Record balances after withdrawAll
        uint256 ownerAfter = owner.balance;
        uint256 contractAfter = address(c).balance;

        // The reference contract transfers the entire contract balance to the owner.
        // Therefore ownerAfter - ownerBefore == contractBefore (owner received all funds) and contractAfter == 0.
        // The mutant that calls withdraw(0) will make ownerAfter - ownerBefore == 0 while contractAfter == contractBefore,
        // violating this property for some inputs; we assert the owner indeed received the funds.
        assertTrue(ownerAfter - ownerBefore == contractBefore);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // drive the contract: deposit some Ether (via fallback), then attempt withdraw by a caller
    // params: depositAmount - amount sent to C to increase its balance; withdrawAmount - amount attempted to withdraw
    // callerIsOwner - if true, this contract acts as owner (it will be owner when deployed by test harness),
    // but to keep general we accept a boolean and require the caller's balance covers deposits.
    receive() external payable {}

    function checkWithdrawBehavior(uint depositAmount, uint withdrawAmount) public payable {
        // must have enough balance in this test contract to send depositAmount
        require(msg.value == depositAmount, "send deposit amount as msg.value");

        // deposit into c by calling fallback (sending Ether without data)
        payable(address(c)).transfer(0); // no-op to keep pattern; transfer to self is allowed
        // Actually perform deposit: call with empty data so C.fallback increments depositsCount
        (bool s,) = address(c).call{value: depositAmount}("");
        require(s, "deposit failed");

        uint before = address(c).balance;

        // attempt to withdraw from c: this call will execute withdraw(withdrawAmount)
        // on P only owner can withdraw; on M anyone can, so this call will reduce balance on M but not on P
        // we invoke withdraw as this contract (msg.sender = this), not necessarily owner
        // The state-changing call must be top-level
        c.withdraw(withdrawAmount);

        uint after = address(c).balance;

        // Assert: if this contract is not the owner then balance must not decrease.
        // We observe owner via c.owner() and compare to address(this).
        // This is a single comparison involving public getters and observed balances.
        assert( (c.owner() != address(this)) ? (after >= before) : true );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // callerAddress is address attempting the withdraw; amount is value to withdraw
    function run(address callerAddress, uint amount) public payable {
        require(callerAddress != address(0) && amount >= 0);
        // make a low-level call to invoke withdraw from callerAddress by using a delegate call style is impossible here,
        // but we can simulate by requiring that msg.sender equals callerAddress when calling run.
        // Enforce that the test runner calls run from the desired caller address
        require(msg.sender == callerAddress);

        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // In the original contract, withdraw reverts unless msg.sender == c.owner().
        // Therefore the general rule: reverted == (msg.sender != c.owner())
        // We can observe c.owner() via its public getter.
        assert(reverted == (msg.sender != c.owner()));
    }
    receive() external payable { }
}

